function showAppExitDialog(){const existing=document.querySelector('#app-exit-dialog');if(existing){existing.focus?.();return}if(typeof accountBusy!=='undefined'&&accountBusy)return;const dialog=document.createElement('dialog');dialog.id='app-exit-dialog';dialog.className='transaction-dialog app-exit-dialog';dialog.setAttribute('aria-labelledby','app-exit-title');dialog.setAttribute('aria-describedby','app-exit-description');dialog.innerHTML='<div class="exit-dialog-body"><span class="exit-dialog-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M10 4H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h5M13 12h8m-4-4 4 4-4 4"/></svg></span><h2 id="app-exit-title">অ্যাপ থেকে বের হবেন?</h2><p id="app-exit-description">আবার ফিরে এসে আপনার হিসাব চালিয়ে যেতে পারবেন।</p><div class="exit-dialog-actions"><button type="button" id="app-exit-no" autofocus>না, থাকব</button><button type="button" class="primary" id="app-exit-yes">হ্যাঁ, বের হব</button></div></div>';document.body.append(dialog);dialog.querySelector('#app-exit-no').onclick=()=>dialog.close();dialog.querySelector('#app-exit-yes').onclick=()=>{if(typeof accountBusy!=='undefined'&&accountBusy)return;dialog.close();if(typeof window.DailyTallyFiles?.exitApp==='function')window.DailyTallyFiles.exitApp()};dialog.addEventListener('click',event=>{if(event.target===dialog){const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)dialog.close()}});dialog.addEventListener('close',()=>dialog.remove());dialog.showModal()}
function handleDailyTallyBack(){const dialogs=Array.from(document.querySelectorAll('dialog[open]'));if(dialogs.length){dialogs[dialogs.length-1].close();return 'handled'}if(typeof accountBusy!=='undefined'&&accountBusy)return 'handled';if(typeof accountPhone!=='undefined'&&accountPhone){if(typeof accountRole!=='undefined'&&accountRole==='admin'&&!adminPersonalMode){if(adminTab!=='overview'){adminTab='overview';render();window.scrollTo?.({top:0,behavior:'smooth'});return 'handled'}}else if(typeof tab!=='undefined'&&(tab!=='ড্যাশবোর্ড'||document.querySelector('#report-back'))){tab='ড্যাশবোর্ড';render();window.scrollTo?.({top:0,behavior:'smooth'});return 'handled'}}showAppExitDialog();return 'handled'}
window.DailyTallyNavigation={back:handleDailyTallyBack};
